#!/usr/bin/env bun
/**
 * render-cases.ts — render every eval case (plus its measured scores) into a readable ../../CASES.md.
 *
 *   bun render-cases.ts
 *
 * Inputs : cases.jsonl (37 existing, Chinese), new-cases-candidates.jsonl (30 candidates, English),
 *          baseline/results.jsonl (bright-rain), haiku-5-5/results.jsonl (claude-haiku-5-5).
 * Output : ../../CASES.md  (generated; do not edit by hand, edit the jsonl and re-run)
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

type KP = { text: string; source: string };
type Case = { prompt_id: string; prompt: string; tags: string[]; origin: string; expected: { key_points: KP[]; note?: string } };
type Row = { prompt_id: string; grade: { coverage: number } };

const ROOT = import.meta.dir;
const jl = <T,>(p: string): T[] => (existsSync(join(ROOT, p)) ? readFileSync(join(ROOT, p), "utf8").trim().split("\n").filter(Boolean).map((l) => JSON.parse(l)) : []);

const existing = jl<Case>("cases.jsonl");
const candidates = jl<Case>("new-cases-candidates.jsonl");

const meanCoverage = (variant: string) => {
  const by = new Map<string, number[]>();
  for (const r of jl<Row>(`${variant}/results.jsonl`)) by.set(r.prompt_id, [...(by.get(r.prompt_id) ?? []), r.grade.coverage]);
  return new Map([...by].map(([id, v]) => [id, v.reduce((a, b) => a + b, 0) / v.length]));
};
const bright = meanCoverage("baseline");
const haiku = meanCoverage("haiku-5-5");
const f = (m: Map<string, number>, id: string) => (m.has(id) ? m.get(id)!.toFixed(2) : "–");

const cell = (s: string) => s.replace(/\|/g, "\\|").replace(/\n/g, " ");
const kind = (c: Case) => c.tags[0];
const hard = (c: Case) => c.tags.filter((t) => t.startsWith("hard:")).map((t) => t.slice(5)).join(", ") || "–";
const groups: { title: string; lang: string; status: string; prefix: (id: string) => string; items: Case[] }[] = [
  { title: "Existing set", lang: "中文", status: "baseline set, gold Claude-written", prefix: (id) => id[0], items: existing },
  { title: "New candidates", lang: "English", status: "CANDIDATE, not yet approved", prefix: (id) => id.replace(/\d+$/, ""), items: candidates },
];
const batchName: Record<string, string> = {
  N: "Mixed (multi-hop, conflict, count, opinion, abstain)",
  FM: "Films, cast, book-vs-film, games",
  MG: "Magic mechanics and creatures",
  BI: "Biography, family trees, dates",
  SC: "Hogwarts and institutions",
  BY: "Beyond Britain, history, false premises",
  E: "E: explain (why/how)",
  F: "F: single fact",
  U: "U: unanswerable (abstain)",
  H: "H: hard set",
};

const anchor = (id: string) => id.toLowerCase();
const out: string[] = [];
const total = existing.length + candidates.length;
out.push(`# All eval cases (${total})`, "", "> Generated by `.evals/wiki-qa/render-cases.ts` from the `.jsonl` files. Do not edit this file by hand.", "");
out.push(
  "Every case is a question for the wiki-QA agent, plus the **key points** a correct answer must contain. Each key point carries a `source`: the page title and a French fragment taken from the wiki snapshot. A key point that says *absence* means the wiki does not contain the fact, and the right answer is to say so.",
  "",
  "| Set | Cases | Language | Status |",
  "|---|---|---|---|",
  ...groups.map((g) => `| ${g.title} | ${g.items.length} | ${g.lang} | ${g.status} |`),
  "",
  "Scores are mean key-point coverage over 3 runs (covered 1, partial 0.5, missing 0): **bright** is `bright-rain` (only the existing set was run), **haiku** is `claude-haiku-5-5`. Judge: `claude-sonnet-5`. See [`metrics.md`](.evals/wiki-qa/metrics.md).",
  "",
  "**Kinds:** `fact` = one short answer; `explain` = why/how/list/compare, several facts; `abstain` = the wiki does not answer, the agent must say so. **Hard tags:** `calc`, `conflict`, `count`, `deep`, `enumerate`, `filter`, `multihop`, `partial`, `premise`, `synthesis`, `uncertain`.",
  "",
);

// ---- index tables ----
out.push("## Index", "");
for (const g of groups) {
  const byPrefix = new Map<string, Case[]>();
  for (const c of g.items) byPrefix.set(g.prefix(c.prompt_id), [...(byPrefix.get(g.prefix(c.prompt_id)) ?? []), c]);
  out.push(`### ${g.title} (${g.lang}, ${g.items.length})`, "");
  for (const [p, cs] of byPrefix) {
    out.push(`**${batchName[p] ?? p}**`, "", "| id | kind | hard | question | key pts | bright | haiku |", "|---|---|---|---|---|---|---|");
    for (const c of cs) out.push(`| [${c.prompt_id}](#${anchor(c.prompt_id)}) | ${kind(c)} | ${hard(c)} | ${cell(c.prompt)} | ${c.expected.key_points.length} | ${f(bright, c.prompt_id)} | ${f(haiku, c.prompt_id)} |`);
    out.push("");
  }
}

// ---- full cases ----
out.push("## Cases in full", "");
for (const g of groups) {
  out.push(`### ${g.title}`, "");
  for (const c of g.items) {
    out.push(`#### ${c.prompt_id}`, "", `\`${c.tags.join("` `")}\``, "", ...c.prompt.split("\n").map((l) => `> ${l}`), "");
    out.push(`**Origin:** ${c.origin.replace(/^web: (https?:\/\/\S+)/, "web: <$1>")}`, "", "**Key points** (all must be covered):", "");
    c.expected.key_points.forEach((k, i) => out.push(`${i + 1}. ${k.text}`, `   - source: *${k.source}*`));
    out.push("");
    if (c.expected.note) out.push(`**Judge note:** ${c.expected.note}`, "");
    out.push(`**Scores:** bright ${f(bright, c.prompt_id)} · haiku ${f(haiku, c.prompt_id)}`, "");
  }
}
writeFileSync(join(ROOT, "../../CASES.md"), out.join("\n"));
console.log(`wrote CASES.md: ${total} cases`);
